Here's the code if you want it:

```c++
#include <Rcpp.h>
using namespace Rcpp;

// [[Rcpp::export]]
double ReflectIndexMed(NumericVector vec, int ind, std::string side) {
  int n = vec.size();
  double out = NA_REAL;
  double med;
  int dist_to_end;
  int dist_to_go;
  double median_dist;
  if (side == "left") {
    NumericVector left = vec[seq(0, ind - 1)];
    med = median(left);
    dist_to_end = ind;
    dist_to_go = 2 * dist_to_end;
    median_dist = 1 + 0.5 * (dist_to_end - 1);
    out = vec[ind] + dist_to_go / median_dist * (med - vec[ind]);
  } else if (side == "right") {
    NumericVector right = vec[seq(ind + 1, n - 1)];
    med = median(right);
    dist_to_end = (n - 1) - ind;
    dist_to_go = 2 * dist_to_end;
    median_dist = 1 + 0.5 * (dist_to_end - 1);
    out = vec[ind] + dist_to_go / median_dist * (med - vec[ind]);
  }
  return out;
